mapper.select:
SELECT COUNT(*)               AS uploadCount,
       COALESCE(SUM(FILE_SZ), 0) AS totalBytes
  FROM ATCH_FILE
 WHERE RGTR_SN = #{rgtrSn}
   AND FILE_SCOPE_CD = #{fileScopeCd}
   AND REG_DT >= UTC_TIMESTAMP(6) - INTERVAL 1 DAY

mapper.update:
UPDATE ATCH_FILE
   SET DEL_YN = 'Y',
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN = #{mdfrSn}
 WHERE ATCH_FILE_SN = #{atchFileSn}
   AND DEL_YN = 'N'

