mapper.update:
UPDATE ATCH_FILE
   SET DEL_YN = 'Y',
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN = #{actorUserSn}
 WHERE ATCH_FILE_SN = #{atchFileSn}
   AND FILE_SCOPE_CD = 'INQR_ATTACH'
   AND ATCH_STTS_CD = 'LINKED'
   AND TRGT_TYPE = 'INQR'
   AND TRGT_ID = #{trgtId}
   AND DEL_YN = 'N'

UPDATE ATCH_FILE
   SET ATCH_VISBLTY_CD = #{visibility},
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN = #{actorUserSn}
 WHERE ATCH_FILE_SN = #{atchFileSn}
   AND FILE_SCOPE_CD = 'INQR_ATTACH'
   AND ATCH_STTS_CD = 'LINKED'
   AND DEL_YN = 'N'
   AND ATCH_VISBLTY_CD <> #{visibility}

UPDATE ATCH_FILE
   SET ATCH_VISBLTY_CD = #{atchVisbltyCd},
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN = #{mdfrSn}
 WHERE FILE_SCOPE_CD = 'INQR_ATTACH'
   AND TRGT_TYPE = 'INQR'
   AND TRGT_ID = #{trgtId}
   AND ATCH_STTS_CD = 'LINKED'
   AND DEL_YN = 'N'
   AND ATCH_VISBLTY_CD <> #{atchVisbltyCd}
